$dir='Assets/Packages/ScenesPackages/PolygonApocalypse/Prefabs/Props'
$names=@('SM_Prop_Bed_Hospital_01','SM_Prop_Bed_Gurney_01','SM_Prop_Bed_Gurney_BodySheet_01','SM_Prop_Bedframe_01','SM_Prop_WheelChair_01','SM_Prop_Medical_IVStand_01','SM_Prop_Medical_Shelf_01','SM_Prop_Medical_Shelf_02','SM_Prop_MedicalBox_01','SM_Prop_Medical_Container_01','SM_Prop_Medical_Container_Broken_01','SM_Prop_Chair_Metal_01','SM_Prop_Chair_Soft_01','SM_Prop_Chair_Folding_01','SM_Prop_Study_Chair_01','SM_Prop_Desk_01','SM_Prop_Desk_02','SM_Prop_Seat_01','SM_Prop_Papers_01','SM_Prop_Papers_02','SM_Prop_Papers_03','SM_Prop_CardboardBox_01')
foreach($n in $names){$p=Join-Path $dir ($n+'.prefab'); if(!(Test-Path $p)){"MISSING $n";continue}; $lines=Get-Content $p; $gos=@{}; foreach($l in $lines){if($l -match '^  m_Name: (.+)$'){$gos[$gos.Count]=$Matches[1]}}; $trans=@(); for($i=0;$i -lt $lines.Count;$i++){if($lines[$i] -eq 'Transform:'){$nm='?';$par='?';$pos='?'; for($j=$i+1;$j -lt [Math]::Min($i+30,$lines.Count);$j++){if($lines[$j] -match '^  m_GameObject: \{fileID: (\d+)\}'){$id=$Matches[1]};if($lines[$j] -match '^  m_LocalPosition: (.+)$'){$pos=$Matches[1]};if($lines[$j] -match '^  m_Father: (.+)$'){$par=$Matches[1]};if($lines[$j] -match '^  m_Children: (.+)$'){$ch=$Matches[1]}}; $trans += "pos=$pos parent=$par children=$ch"}}; "`n$n`n  GO: $($gos -join ' | ')`n  TRANS: $($trans -join ' || ')"}
